#include "KS/SRC/ks/SaveLoadFrontEnd_shared.h"

class NamesMenuReleased : public FEMultiMenu
{
    char names_menu_data[0x208 - sizeof(FEMultiMenu)];
    PanelQuad* box;
    PanelQuad* arrows[2][2];
    PanelQuad* lines[10];
    PanelQuad* top_line;
    PanelQuad* side_line;
public:
    void SetPQIndices() __asm__("SetPQIndices__9NamesMenu");
};

void NamesMenuReleased::SetPQIndices()
{
	box = GetPointer("box_right");
	arrows[0][0] = GetPointer("button_off_01");
	arrows[0][1] = GetPointer("button_on_01");
	arrows[1][0] = GetPointer("button_off_02");
	arrows[1][1] = GetPointer("button_on_02");
	top_line = GetPointer("line_right_01");
	side_line = GetPointer("line_right_12");
	for(int i=0; i<10; i++)
	{
		stringx tmp = stringx(i+2);
		if(i+2 < 10) tmp = "0"+tmp;
		lines[i] = GetPointer(("line_right_"+tmp).data());
	}
}
